<script setup lang="ts">
import { computed, ref } from 'vue'
import { BedDouble, Check, ChevronLeft, ChevronRight, Download, Plus, Printer, Search, Utensils, X } from '@lucide/vue'
import { eventRates, type EventRate } from '@/features/events/stores/eventRates'
import { blankTasks, events, sampleEvent, type EventFolioEntry, type EventKind, type EventStatus, type HotelEvent } from '@/features/events/stores/eventData'

type EventTab = 'Event Master' | 'Invoices' | 'Receipts' | 'Folios'
type FunctionTab = 'Event' | 'Setup' | 'Catering' | 'Timeline' | 'Tasks'
type CalendarMode = 'Day' | 'Week' | 'Month'
const tabs: EventTab[] = ['Event Master', 'Invoices', 'Receipts', 'Folios']
const activeTab = ref<EventTab>('Event Master')
const activeView = ref<'Table' | 'Calendar' | 'Gantt' | 'Function'>('Table')
const calendarMode = ref<CalendarMode>('Month')
const calendarDate = ref(new Date())
const search = ref('')
const typeFilter = ref('All event types')
const dateFilter = ref('All dates')
const showNewEvent = ref(false)
const functionEvent = ref<HotelEvent | null>(null)
const functionTab = ref<FunctionTab>('Event')
const selectedFolio = ref<HotelEvent | null>(null)
const folioFormOpen = ref(false)
const receiptFormOpen = ref(false)
const folioEntryToVoid = ref<EventFolioEntry | null>(null)
const voidReason = ref('')
const folioForm = ref({ type: 'Charge' as 'Charge' | 'Debit note', description: '', amount: '' })
const receiptForm = ref({ method: 'Cash', amount: '', reference: '' })
const savedToast = ref('')
const form = ref({ name: '', client: '', kind: 'Wedding' as EventKind, accommodation: 'Non-residential' as HotelEvent['accommodation'], venue: 'Grand Ballroom', start: '', end: '', startTime: '09:00', pax: '1', amount: '', phone: '', email: '' })
const selectedRateIds = ref<string[]>([])
const rateQuantities = ref<Record<string, number>>({})
const visibleEvents = computed(() => events.value.filter((event) => {
  const query = search.value.trim().toLowerCase()
  const matchesSearch = !query || [event.id, event.name, event.client, event.venue].some((value) => value.toLowerCase().includes(query))
  const matchesType = typeFilter.value === 'All event types' || event.kind === typeFilter.value
  const now = new Date()
  const matchesDate = dateFilter.value === 'All dates' || (dateFilter.value === 'Today' && event.start === dateKey(now)) || (dateFilter.value === 'This month' && event.start.slice(0, 7) === dateKey(now).slice(0, 7))
  return matchesSearch && matchesType && matchesDate
}).sort((a, b) => a.start.localeCompare(b.start)))
const monthLabel = computed(() => calendarDate.value.toLocaleDateString('en-PH', { month: 'long', year: 'numeric' }))
const calendarDays = computed(() => {
  const first = new Date(calendarDate.value.getFullYear(), calendarDate.value.getMonth(), 1)
  const offset = (first.getDay() + 6) % 7
  const start = new Date(first)
  start.setDate(first.getDate() - offset)
  const cells = calendarMode.value === 'Month' ? 42 : calendarMode.value === 'Week' ? 7 : 1
  if (calendarMode.value === 'Day') {
    const day = new Date(calendarDate.value)
    day.setHours(0, 0, 0, 0)
    return [day]
  }
  const weekStart = new Date(calendarDate.value)
  weekStart.setHours(0, 0, 0, 0)
  weekStart.setDate(weekStart.getDate() - ((weekStart.getDay() + 6) % 7))
  const base = calendarMode.value === 'Week' ? weekStart : start
  return Array.from({ length: cells }, (_, index) => { const day = new Date(base); day.setDate(base.getDate() + index); return day })
})
const calendarTitle = computed(() => {
  if (calendarMode.value === 'Month') return monthLabel.value
  if (calendarMode.value === 'Day') return calendarDate.value.toLocaleDateString('en-PH', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
  const start = calendarDays.value[0]
  const end = calendarDays.value[6]
  return `${start?.toLocaleDateString('en-PH', { day: 'numeric', month: 'short' })} – ${end?.toLocaleDateString('en-PH', { day: 'numeric', month: 'short', year: 'numeric' })}`
})
const functionRows = computed(() => visibleEvents.value.map((event) => ({ event, taskCount: event.tasks.length, doneCount: event.tasks.filter((task) => task.complete).length })))
const applicableRates = computed(() => eventRates.value.filter((rate) => rate.active && (rate.client === 'All clients' || rate.client === form.value.client) && (!form.value.start || rate.alwaysEffective || rate.from <= form.value.start) && (!form.value.end || rate.alwaysEffective || rate.to >= form.value.end)))
const selectedApplicableRates = computed(() => applicableRates.value.filter((rate) => selectedRateIds.value.includes(rate.id)))
const selectedRateTotal = computed(() => selectedApplicableRates.value.reduce((sum, rate) => sum + rate.amount * (rateQuantities.value[rate.id] || 1), 0))
const formTotal = computed(() => selectedApplicableRates.value.length ? selectedRateTotal.value + (Number(form.value.amount) || 0) : Number(form.value.amount) || 0)
const folioTabsCounts = computed(() => ({ Invoices: events.value.filter((event) => event.invoiceNumber).length, Receipts: events.value.reduce((sum, event) => sum + event.folioEntries.filter((entry) => entry.type === 'Receipt').length, 0), Folios: events.value.length }))
function tabCount(tab: EventTab) { return tab === 'Event Master' ? events.value.length : folioTabsCounts.value[tab] }
const ganttDays = computed(() => Array.from({ length: new Date(calendarDate.value.getFullYear(), calendarDate.value.getMonth() + 1, 0).getDate() }, (_, index) => index + 1))
const ganttData = computed(() => {
  const year = calendarDate.value.getFullYear()
  const month = calendarDate.value.getMonth()
  const monthStart = new Date(year, month, 1)
  const monthEnd = new Date(year, month + 1, 0)
  const monthStartKey = dateKey(monthStart)
  const monthEndKey = dateKey(monthEnd)
  const venues = [...new Set([...events.value.map((event) => event.venue), 'Grand Ballroom', 'Boardroom', 'Garden Pavilion'])]
  return venues.map((venue) => {
    const rows = visibleEvents.value.filter((event) => event.venue === venue && event.start <= monthEndKey && event.end >= monthStartKey).map((event, index) => {
      const eventStart = new Date(`${event.start}T00:00:00`)
      const eventEnd = new Date(`${event.end}T00:00:00`)
      const startDay = event.start < monthStartKey ? 0 : eventStart.getDate() - 1
      const endDayExclusive = event.end > monthEndKey ? ganttDays.value.length : eventEnd.getDate()
      return { event, startDay, span: Math.max(1, endDayExclusive - startDay), lane: index }
    })
    return { venue, rows, height: Math.max(48, rows.length * 32 + 8) }
  })
})
const dailyPax = computed(() => ganttDays.value.map((day) => {
  const key = dateKey(new Date(calendarDate.value.getFullYear(), calendarDate.value.getMonth(), day))
  return visibleEvents.value.filter((event) => event.start <= key && event.end >= key).reduce((sum, event) => sum + event.pax, 0)
}))

function dateKey(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` }
function formatDate(value: string) { return new Date(`${value}T00:00:00`).toLocaleDateString('en-PH', { day: 'numeric', month: 'short' }) }
function dayCount(event: HotelEvent) { return Math.max(1, Math.round((new Date(`${event.end}T00:00:00`).getTime() - new Date(`${event.start}T00:00:00`).getTime()) / 86400000) + 1) }
function money(amount: number) { return `₱${amount.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function statusClass(status: EventStatus) { return status === 'Confirmed' ? 'bg-[#e7f5ed] text-[#38774f]' : status === 'Completed' ? 'bg-[#e8f0fa] text-[#456d9a]' : 'bg-[#fff3dc] text-[#916b35]' }
function toggleRate(rate: EventRate) {
  if (selectedRateIds.value.includes(rate.id)) selectedRateIds.value = selectedRateIds.value.filter((id) => id !== rate.id)
  else {
    selectedRateIds.value = [...selectedRateIds.value, rate.id]
    rateQuantities.value[rate.id] = rate.type === 'Conference' || rate.type === 'Lunch' || rate.type === 'Dinner' ? Number(form.value.pax) || 1 : 1
  }
}
function eventCharges(event: HotelEvent) { return event.folioEntries.filter((entry) => entry.status === 'Posted' && entry.type !== 'Receipt').reduce((sum, entry) => sum + entry.amount, 0) }
function eventPayments(event: HotelEvent) { return event.folioEntries.filter((entry) => entry.status === 'Posted' && entry.type === 'Receipt').reduce((sum, entry) => sum + entry.amount, 0) }
function eventBalance(event: HotelEvent) { return eventCharges(event) - eventPayments(event) }
function folioNumber(event: HotelEvent) { return `FOL-${event.id.slice(4)}` }
function openFolio(event: HotelEvent) { selectedFolio.value = event; folioFormOpen.value = false; receiptFormOpen.value = false }
function openFolioEntry(type: 'Charge' | 'Debit note') { folioForm.value = { type, description: '', amount: '' }; folioFormOpen.value = true }
function addFolioEntry() {
  const amount = Number(folioForm.value.amount)
  if (!selectedFolio.value || !folioForm.value.description.trim() || !Number.isFinite(amount) || amount <= 0) return
  selectedFolio.value.folioEntries.push({ id: `EFL-${Date.now()}`, date: dateKey(new Date()), type: folioForm.value.type, description: folioForm.value.description.trim(), amount, status: 'Posted' })
  folioFormOpen.value = false
}
function addReceipt() {
  const amount = Number(receiptForm.value.amount)
  if (!selectedFolio.value || !Number.isFinite(amount) || amount <= 0 || amount > eventBalance(selectedFolio.value) + 0.009) return
  selectedFolio.value.folioEntries.push({ id: `ER-${Date.now()}`, date: dateKey(new Date()), type: 'Receipt', description: 'Event payment received', amount, method: receiptForm.value.method, reference: receiptForm.value.reference.trim() || undefined, status: 'Posted' })
  receiptFormOpen.value = false
}
function invoiceEvent(event: HotelEvent) { event.invoiceNumber ||= `EINV-${event.id.slice(4)}`; event.invoiceStatus = 'Invoiced'; activeTab.value = 'Invoices' }
function voidFolioEntry() {
  if (!folioEntryToVoid.value || !voidReason.value.trim()) return
  folioEntryToVoid.value.status = 'Voided'; folioEntryToVoid.value.voidReason = voidReason.value.trim(); folioEntryToVoid.value = null; voidReason.value = ''
}
function ganttColor(status: EventStatus) { return status === 'Confirmed' ? '#079669' : status === 'Completed' ? '#5479ad' : '#df7b12' }
function eventsOn(date: Date) { const key = dateKey(date); return visibleEvents.value.filter((event) => event.start <= key && event.end >= key) }
function openFunction(event: HotelEvent) { functionEvent.value = event; functionTab.value = 'Event' }
function shiftCalendar(direction: number) { const next = new Date(calendarDate.value); if (activeView.value === 'Gantt' || calendarMode.value === 'Month') { next.setDate(1); next.setMonth(next.getMonth() + direction) } else next.setDate(next.getDate() + (calendarMode.value === 'Week' ? 7 * direction : direction)); calendarDate.value = next }
function goToday() { calendarDate.value = new Date() }
function setCalendarDate(event: Event) { const value = (event.target as HTMLInputElement).value; if (value) calendarDate.value = new Date(`${value}T12:00:00`) }
function setGanttMonth(event: Event) { const value = (event.target as HTMLInputElement).value; if (value) calendarDate.value = new Date(`${value}-01T12:00:00`) }
function changeView(view: 'Table' | 'Calendar' | 'Gantt' | 'Function') { activeView.value = view; if (view === 'Calendar') calendarMode.value = 'Month' }
function removeTimelineItem(index: number) { if (functionEvent.value) functionEvent.value.timeline.splice(index, 1) }
function closeForm() { showNewEvent.value = false; selectedRateIds.value = []; rateQuantities.value = {}; form.value = { name: '', client: '', kind: 'Wedding', accommodation: 'Non-residential', venue: 'Grand Ballroom', start: '', end: '', startTime: '09:00', pax: '1', amount: '', phone: '', email: '' } }
function saveEvent() {
  if (!form.value.name.trim() || !form.value.client.trim() || !form.value.start || !form.value.end || form.value.end < form.value.start || Number(form.value.pax) < 1 || (!form.value.amount && !selectedApplicableRates.value.length) || Number(form.value.amount) < 0) return
  const id = `EVT-${String(Math.max(0, ...events.value.map((event) => Number(event.id.slice(4)))) + 1).padStart(3, '0')}`
  const tasks = blankTasks(form.value.start)
  const newEvent = sampleEvent({ id, name: form.value.name.trim(), client: form.value.client.trim(), kind: form.value.kind, accommodation: form.value.accommodation, venue: form.value.venue, start: form.value.start, end: form.value.end, startTime: form.value.startTime, pax: Number(form.value.pax), status: 'Quote', coordinator: 'Unassigned', amount: formTotal.value, contactName: form.value.client.trim(), phone: form.value.phone.trim(), email: form.value.email.trim(), tasks })
  events.value.unshift(newEvent)
  form.value = { name: '', client: '', kind: 'Wedding', accommodation: 'Non-residential', venue: 'Grand Ballroom', start: '', end: '', startTime: '09:00', pax: '1', amount: '', phone: '', email: '' }
  selectedRateIds.value = []; rateQuantities.value = {}
  showNewEvent.value = false
}
function advanceEventStatus() {
  if (!functionEvent.value) return
  if (functionEvent.value.status === 'Quote') functionEvent.value.status = 'Confirmed'
  else if (functionEvent.value.status === 'Confirmed') functionEvent.value.status = 'Completed'
}
function saveFunction() { savedToast.value = 'Function sheet saved. Department duties are shared in the event briefing.'; window.setTimeout(() => { savedToast.value = '' }, 3500) }
function printEvents() { window.print() }
function exportEvents() {
  const header = ['Event ID', 'Event', 'Client', 'Type', 'Venue', 'Start', 'End', 'Days', 'Pax', 'Status', 'Coordinator', 'Amount']
  const rows = visibleEvents.value.map((event) => [event.id, event.name, event.client, event.kind, event.venue, event.start, event.end, dayCount(event), event.pax, event.status, event.coordinator, event.amount])
  const csv = [header, ...rows].map((row) => row.map((value) => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\n')
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }))
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'event-master.csv'; anchor.click(); URL.revokeObjectURL(url)
}
</script>

<template>
  <section class="space-y-4">
    <header><p class="eyebrow">Events &amp; Conferences</p><h1 class="mt-1 font-serif text-[29px] font-medium tracking-[-0.035em] text-[#30243e]">Event Management</h1><p class="mt-1 text-[10px] text-[#817987]">Plan weddings, conferences, and workshops with one briefing for every hotel team.</p></header>
    <p v-if="savedToast" class="rounded-md border border-[#cfe5d8] bg-[#f0f8f3] px-3 py-2 text-[9px] text-[#44805b]">{{ savedToast }}</p>
    <div class="overflow-hidden rounded-lg border border-[#e5e8eb] bg-white">
      <nav class="flex flex-wrap gap-1 border-b border-[#e8ebef] bg-[#f8fafc] p-2" aria-label="Event management sections"><button v-for="tab in tabs" :key="tab" class="rounded-md px-3 py-2 text-[9px] font-medium" :class="activeTab === tab ? 'border border-[#e2e6eb] bg-white text-[#26323c] shadow-sm' : 'text-[#697681] hover:bg-white'" @click="activeTab = tab">{{ tab }} <span>({{ tabCount(tab) }})</span></button></nav>
      <template v-if="activeTab === 'Event Master'">
        <div class="flex flow-row  items-center gap-2 border-b border-[#edf0f3] p-3">
          <label class="client-search flex-1"><Search :size="12" /><span class="sr-only">Search events</span><input v-model="search" placeholder="Search event, client, venue..." />
          </label>
          <select v-model="typeFilter" class="report-select ">
            <option>All event types</option>
            <option>Wedding</option>
            <option>Conference</option>
            <option>Workshop</option>
            <option>Social event</option>
          </select><span class="mr-auto text-[9px] text-[#77838b]">{{ visibleEvents.length }} events</span>
          <select v-model="dateFilter" class="report-select ">
            <option>All dates</option>
            <option>Today</option>
            <option>This month</option>
          </select>
        </div>
        <section class="p-3">
          <div class="mb-3 flex flex-wrap items-center justify-between gap-2"><h2 class="text-[12px] font-semibold text-[#34414a]">{{ activeView === 'Function' ? 'Function schedule & department briefing' : 'Event Master' }}</h2><div class="flex flex-wrap gap-1"><button v-for="view in (['Table', 'Calendar', 'Gantt', 'Function'] as const)" :key="view" class="rounded-md border px-2.5 py-1.5 text-[8px]" :class="activeView === view ? 'border-[#1768d5] bg-[#1768d5] text-white' : 'border-[#e3e7eb] text-[#58656f] hover:bg-[#f8fafc]'" @click="changeView(view)">{{ view }}</button><button class="rounded-md border border-[#e3e7eb] px-2.5 py-1.5 text-[8px] text-[#58656f]" @click="printEvents"><Printer :size="10" class="mr-1 inline" />PDF</button><button class="rounded-md border border-[#e3e7eb] px-2.5 py-1.5 text-[8px] text-[#58656f]" @click="exportEvents"><Download :size="10" class="mr-1 inline" />Excel</button><button class="inline-flex items-center rounded-md border border-[#69489a] px-3 py-2 text-[9px] font-semibold text-white shadow-sm transition hover:brightness-95 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#69489a]" style="background-color:#69489a" @click="showNewEvent = true"><Plus :size="12" class="mr-1 inline" />New event</button></div></div>

          <div v-if="activeView === 'Table'" class="overflow-x-auto rounded-md border border-[#edf0f3]"><table class="w-full min-w-[950px] border-collapse text-left"><thead class="bg-[#fafbfc] text-[8px] font-medium text-[#67737d]"><tr><th class="px-2.5 py-2.5">Event ID</th><th class="px-2.5 py-2.5">Event</th><th class="px-2.5 py-2.5">Type</th><th class="px-2.5 py-2.5">Venue</th><th class="px-2.5 py-2.5">Start</th><th class="px-2.5 py-2.5">End</th><th class="px-2.5 py-2.5 text-right">Days</th><th class="px-2.5 py-2.5 text-right">Pax</th><th class="px-2.5 py-2.5">Status</th><th class="px-2.5 py-2.5">Coordinator</th><th class="px-2.5 py-2.5 text-right">Amount</th></tr></thead><tbody><tr v-for="event in visibleEvents" :key="event.id" class="cursor-pointer border-t border-[#edf0f3] text-[9px] text-[#46515a] hover:bg-[#fbfafc]" @click="openFunction(event)"><td class="px-2.5 py-2.5 text-[#7d8991]">{{ event.id }}</td><td class="max-w-[180px] px-2.5 py-2.5"><strong class="block truncate text-[9px] text-[#28343c]">{{ event.name }}</strong><span class="mt-0.5 block truncate text-[8px] text-[#8a959c]">{{ event.client }}</span></td><td class="px-2.5 py-2.5">{{ event.kind }}</td><td class="px-2.5 py-2.5">{{ event.venue }}</td><td class="whitespace-nowrap px-2.5 py-2.5">{{ formatDate(event.start) }}</td><td class="whitespace-nowrap px-2.5 py-2.5">{{ formatDate(event.end) }}</td><td class="px-2.5 py-2.5 text-right">{{ dayCount(event) }}</td><td class="px-2.5 py-2.5 text-right">{{ event.pax }}</td><td class="px-2.5 py-2.5"><span class="rounded-full px-2 py-1 text-[8px]" :class="statusClass(event.status)">{{ event.status }}</span></td><td class="px-2.5 py-2.5 text-[#94652e]">{{ event.coordinator }}</td><td class="whitespace-nowrap px-2.5 py-2.5 text-right font-medium">{{ money(event.amount) }}</td></tr><tr v-if="visibleEvents.length === 0"><td colspan="11" class="px-4 py-10 text-center text-[10px] text-[#82909a]">No events match your filters.</td></tr></tbody></table></div>

          <div v-else-if="activeView === 'Calendar'" class="rounded-md border border-[#edf0f3]">
            <div class="flex flex-wrap items-center justify-between gap-2 border-b border-[#edf0f3] p-3"><div class="flex items-center gap-2"><button class="secondary-button px-2 py-1.5" aria-label="Previous period" @click="shiftCalendar(-1)"><ChevronLeft :size="13" /></button><button class="secondary-button px-2.5 py-1.5" @click="goToday">Today</button><button class="secondary-button px-2 py-1.5" aria-label="Next period" @click="shiftCalendar(1)"><ChevronRight :size="13" /></button><h3 class="ml-1 text-[11px] font-semibold text-[#34414a]">{{ calendarTitle }}</h3></div><div class="flex gap-1"> <button v-for="mode in (['Day','Week','Month'] as const)" :key="mode" class="rounded border px-2.5 py-1.5 text-[8px]" :class="calendarMode === mode ? 'border-[#1768d5] bg-[#1768d5] text-white' : 'border-[#e3e7eb] text-[#58656f]'" @click="calendarMode = mode">{{ mode }}</button></div><input type="date" class="report-date" :value="dateKey(calendarDate)" @change="setCalendarDate" /></div>
            <div v-if="calendarMode === 'Month'" class="grid grid-cols-7"><div v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day" class="border-b border-r border-[#edf0f3] bg-[#fafbfc] px-2 py-2 text-center text-[8px] font-medium text-[#7a8791]">{{ day }}</div><div v-for="date in calendarDays" :key="dateKey(date)" class="min-h-[94px] border-b border-r border-[#edf0f3] p-1.5" :class="date.getMonth() !== calendarDate.getMonth() ? 'bg-[#fafbfc] text-[#a6afb6]' : ''"><span class="text-[8px]">{{ date.getDate() }}</span><button v-for="event in eventsOn(date).slice(0, 2)" :key="event.id" class="mt-1 block w-full truncate rounded px-1.5 py-1 text-left text-[7px]" :class="event.status === 'Confirmed' ? 'bg-[#e4f5ed] text-[#39764f]' : 'bg-[#fff2df] text-[#8c6838]'" @click="openFunction(event)">{{ event.startTime }} · {{ event.name }}</button><span v-if="eventsOn(date).length > 2" class="mt-1 block text-[7px] text-[#817987]">+{{ eventsOn(date).length - 2 }} more</span></div></div>
            <div v-else-if="calendarMode === 'Week'" class="grid grid-cols-7"><div v-for="date in calendarDays" :key="dateKey(date)" class="min-h-[240px] border-r border-[#edf0f3]"><div class="border-b border-[#edf0f3] bg-[#fafbfc] px-2 py-2 text-center"><span class="block text-[8px] text-[#7a8791]">{{ date.toLocaleDateString('en-PH', { weekday: 'short' }) }}</span><strong class="text-[10px] text-[#34414a]">{{ date.getDate() }}</strong></div><button v-for="event in eventsOn(date)" :key="event.id" class="mx-1 mt-2 block w-[calc(100%-8px)] rounded px-1.5 py-1.5 text-left text-[7px]" :class="event.status === 'Confirmed' ? 'bg-[#e4f5ed] text-[#39764f]' : 'bg-[#fff2df] text-[#8c6838]'" @click="openFunction(event)"><strong class="block">{{ event.startTime }}</strong>{{ event.name }}</button></div></div>
            <div v-else class="min-h-[260px] p-3"><p class="mb-2 text-[9px] font-medium text-[#66737d]">{{ eventsOn(calendarDays[0]!).length }} scheduled event(s)</p><button v-for="event in eventsOn(calendarDays[0]!)" :key="event.id" class="mb-2 flex w-full items-center justify-between rounded-md border border-[#edf0f3] p-3 text-left hover:bg-[#fbfafc]" @click="openFunction(event)"><span><strong class="block text-[10px] text-[#34414a]">{{ event.name }}</strong><small class="text-[8px] text-[#7a8791]">{{ event.startTime }} · {{ event.venue }} · {{ event.pax }} guests</small></span><span class="rounded-full px-2 py-1 text-[8px]" :class="statusClass(event.status)">{{ event.status }}</span></button><p v-if="eventsOn(calendarDays[0]!).length === 0" class="py-10 text-center text-[10px] text-[#82909a]">No events scheduled for this day.</p></div>
          </div>

          <div v-else-if="activeView === 'Gantt'" class="overflow-hidden rounded-md border border-[#edf0f3]">
            <div class="flex flex-wrap items-center justify-between gap-2 border-b border-[#edf0f3] p-3"><div><h3 class="text-[11px] font-semibold text-[#34414a]">{{ monthLabel }}</h3><p class="mt-0.5 text-[8px] text-[#7d8991]">{{ dateKey(new Date(calendarDate.getFullYear(), calendarDate.getMonth(), 1)) }} → {{ dateKey(new Date(calendarDate.getFullYear(), calendarDate.getMonth() + 1, 0)) }} · daily guest totals</p></div><div class="flex items-center gap-1.5"><button class="secondary-button px-2 py-1.5" aria-label="Previous month" @click="shiftCalendar(-1)"><ChevronLeft :size="13" /></button><button class="secondary-button px-2.5 py-1.5" @click="goToday">Today</button><button class="secondary-button px-2 py-1.5" aria-label="Next month" @click="shiftCalendar(1)"><ChevronRight :size="13" /></button><input type="month" class="report-date" :value="`${calendarDate.getFullYear()}-${String(calendarDate.getMonth() + 1).padStart(2, '0')}`" @change="setGanttMonth" /></div></div>
            <div class="flex flex-wrap gap-3 border-b border-[#edf0f3] px-3 py-2"><span v-for="status in (['Confirmed', 'Quote', 'Completed'] as const)" :key="status" class="inline-flex items-center gap-1.5 text-[8px] text-[#59656e]"><i class="size-2 rounded-sm" :style="{ backgroundColor: ganttColor(status) }"></i>{{ status }}</span></div>
            <div class="overflow-x-auto"><div class="min-w-[1180px]">
              <div class="grid border-b border-[#edf0f3] bg-[#fafbfc]" :style="{ gridTemplateColumns: `150px repeat(${ganttDays.length}, minmax(30px, 1fr))` }"><div class="sticky left-0 z-[1] border-r border-[#edf0f3] bg-[#fafbfc] px-3 py-2.5 text-[8px] font-semibold uppercase tracking-[0.06em] text-[#67737d]">Venue</div><div v-for="day in ganttDays" :key="day" class="border-r border-[#edf0f3] px-0.5 py-2 text-center text-[7px] text-[#77838b]"><span class="block">{{ new Date(calendarDate.getFullYear(), calendarDate.getMonth(), day).toLocaleDateString('en-PH', { weekday: 'short' }).slice(0, 1) }}</span><strong class="mt-0.5 block font-medium text-[#53616a]">{{ day }}</strong></div></div>
              <div v-for="row in ganttData" :key="row.venue" class="grid border-b border-[#edf0f3]" :style="{ gridTemplateColumns: `150px minmax(0, 1fr)` }"><div class="sticky left-0 z-[1] border-r border-[#edf0f3] bg-white px-3 py-2.5"><strong class="block text-[9px] font-medium text-[#3d4851]">{{ row.venue }}</strong><span class="mt-0.5 block text-[7px] text-[#87929a]">{{ row.rows.length }} event{{ row.rows.length === 1 ? '' : 's' }}</span></div><div class="relative grid" :style="{ height: `${row.height}px`, gridTemplateColumns: `repeat(${ganttDays.length}, minmax(30px, 1fr))` }"><span v-for="day in ganttDays" :key="day" class="border-r border-[#f0f2f4]" :class="day % 2 === 0 ? 'bg-[#fcfcfd]' : 'bg-white'"></span><button v-for="bar in row.rows" :key="bar.event.id" class="absolute z-[1] h-[23px] min-w-[22px] truncate rounded px-1.5 text-left text-[7px] font-semibold text-white shadow-sm transition hover:brightness-95 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-[#30243e]" :style="{ left: `${bar.startDay / ganttDays.length * 100}%`, width: `${bar.span / ganttDays.length * 100}%`, top: `${bar.lane * 32 + 6}px`, backgroundColor: ganttColor(bar.event.status) }" :title="`${bar.event.name} · ${formatDate(bar.event.start)} – ${formatDate(bar.event.end)} · ${bar.event.pax} guests · ${bar.event.status}`" @click="openFunction(bar.event)">{{ bar.event.pax }} · {{ bar.event.name }}</button></div></div>
              <div class="grid bg-[#fafbfc]" :style="{ gridTemplateColumns: `150px repeat(${ganttDays.length}, minmax(30px, 1fr))` }"><div class="sticky left-0 z-[1] border-r border-[#edf0f3] bg-[#fafbfc] px-3 py-2.5 text-[8px] font-semibold text-[#53616a]">Daily pax</div><div v-for="(pax, index) in dailyPax" :key="index" class="border-r border-[#edf0f3] px-0.5 py-2.5 text-center text-[7px] text-[#68757e]">{{ pax || '—' }}</div></div>
            </div></div>
          </div>

          <div v-else class="space-y-3"><div class="rounded-md border border-[#dce6f5] bg-[#f4f8fe] px-3 py-2.5"><strong class="text-[9px] text-[#315f9e]">Department briefing</strong><p class="mt-0.5 text-[8px] text-[#667b96]">One function sheet shares the schedule and assigned duties with Reservations, Kitchen, and Housekeeping.</p></div><div class="overflow-x-auto rounded-md border border-[#edf0f3]"><table class="w-full min-w-[950px] border-collapse text-left"><thead class="bg-[#fafbfc] text-[8px] uppercase tracking-[0.04em] text-[#67737d]"><tr><th class="px-2.5 py-2.5">Event / date</th><th class="px-2.5 py-2.5">Organization</th><th class="px-2.5 py-2.5">Venue / type</th><th class="px-2.5 py-2.5">Pax</th><th class="px-2.5 py-2.5">Reservations duty</th><th class="px-2.5 py-2.5">Kitchen duty</th><th class="px-2.5 py-2.5">Housekeeping duty</th><th class="px-2.5 py-2.5">Tasks</th></tr></thead><tbody><tr v-for="row in functionRows" :key="row.event.id" class="cursor-pointer border-t border-[#edf0f3] text-[8px] text-[#46515a] hover:bg-[#fbfafc]" @click="openFunction(row.event)"><td class="px-2.5 py-2.5"><strong class="block text-[#34414a]">{{ row.event.name }}</strong><span class="text-[#87929a]">{{ formatDate(row.event.start) }} · {{ row.event.startTime }}</span></td><td class="px-2.5 py-2.5">{{ row.event.client }}</td><td class="px-2.5 py-2.5">{{ row.event.venue }} · {{ row.event.kind }}</td><td class="px-2.5 py-2.5">{{ row.event.pax }}</td><td class="max-w-[170px] px-2.5 py-2.5">{{ row.event.tasks.find((task) => task.department === 'Reservations')?.duty }}</td><td class="max-w-[170px] px-2.5 py-2.5">{{ row.event.tasks.find((task) => task.department === 'Kitchen')?.duty }}</td><td class="max-w-[170px] px-2.5 py-2.5">{{ row.event.tasks.find((task) => task.department === 'Housekeeping')?.duty }}</td><td class="px-2.5 py-2.5">{{ row.doneCount }}/{{ row.taskCount }} done</td></tr></tbody></table></div></div>
        </section>
      </template>
      <section v-else-if="activeTab === 'Folios'" class="p-3"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h2 class="text-[12px] font-semibold text-[#34414a]">Event folios</h2><p class="mt-0.5 text-[9px] text-[#7d8991]">Track event charges, receipts, and balances by booking.</p></div><span class="rounded-full bg-[#e8f5ed] px-2.5 py-1 text-[8px] text-[#39764f]">{{ events.length }} event accounts</span></div><div class="overflow-x-auto rounded-md border border-[#edf0f3]"><table class="w-full min-w-[850px] border-collapse text-left"><thead class="bg-[#fafbfc] text-[8px] font-medium text-[#67737d]"><tr><th class="px-3 py-2.5">Folio</th><th class="px-3 py-2.5">Event / organization</th><th class="px-3 py-2.5">Event date</th><th class="px-3 py-2.5 text-right">Charges</th><th class="px-3 py-2.5 text-right">Payments</th><th class="px-3 py-2.5 text-right">Amount due</th><th class="px-3 py-2.5">Status</th><th class="px-3 py-2.5"></th></tr></thead><tbody><tr v-for="event in events" :key="event.id" class="border-t border-[#edf0f3] text-[9px] text-[#46515a]"><td class="px-3 py-2.5 font-medium text-[#69489a]">{{ folioNumber(event) }}</td><td class="px-3 py-2.5"><strong class="block text-[#28343c]">{{ event.name }}</strong><span class="text-[8px] text-[#8a959c]">{{ event.client }} · {{ event.id }}</span></td><td class="px-3 py-2.5">{{ formatDate(event.start) }}</td><td class="px-3 py-2.5 text-right">{{ money(eventCharges(event)) }}</td><td class="px-3 py-2.5 text-right">{{ money(eventPayments(event)) }}</td><td class="px-3 py-2.5 text-right font-semibold" :class="eventBalance(event) > 0 ? 'text-[#a25454]' : 'text-[#39764f]'">{{ money(eventBalance(event)) }}</td><td class="px-3 py-2.5"><span class="rounded-full bg-[#e8f5ed] px-2 py-1 text-[8px] text-[#39764f]">{{ event.invoiceStatus || 'Open' }}</span></td><td class="px-3 py-2.5 text-right"><button class="rounded border border-[#e3e7eb] px-2.5 py-1.5 text-[8px] text-[#5b476f] hover:bg-[#f8f5fb]" @click="openFolio(event)">View folio</button></td></tr></tbody></table></div></section>
      <section v-else-if="activeTab === 'Invoices'" class="p-3"><div class="mb-3"><h2 class="text-[12px] font-semibold text-[#34414a]">Event invoices</h2><p class="mt-0.5 text-[9px] text-[#7d8991]">Invoices created from event folios.</p></div><div class="overflow-x-auto rounded-md border border-[#edf0f3]"><table class="w-full min-w-[700px] border-collapse text-left"><thead class="bg-[#fafbfc] text-[8px] font-medium text-[#67737d]"><tr><th class="px-3 py-2.5">Invoice</th><th class="px-3 py-2.5">Event / bill to</th><th class="px-3 py-2.5">Date</th><th class="px-3 py-2.5 text-right">Total</th><th class="px-3 py-2.5 text-right">Paid</th><th class="px-3 py-2.5 text-right">Balance</th><th class="px-3 py-2.5"></th></tr></thead><tbody><tr v-for="event in events.filter((item) => item.invoiceNumber)" :key="event.id" class="border-t border-[#edf0f3] text-[9px] text-[#46515a]"><td class="px-3 py-2.5 font-medium text-[#69489a]">{{ event.invoiceNumber }}</td><td class="px-3 py-2.5"><strong class="block text-[#28343c]">{{ event.name }}</strong><span class="text-[8px] text-[#8a959c]">{{ event.client }}</span></td><td class="px-3 py-2.5">{{ formatDate(event.start) }}</td><td class="px-3 py-2.5 text-right">{{ money(eventCharges(event)) }}</td><td class="px-3 py-2.5 text-right">{{ money(eventPayments(event)) }}</td><td class="px-3 py-2.5 text-right">{{ money(eventBalance(event)) }}</td><td class="px-3 py-2.5 text-right"><button class="text-[8px] text-[#69489a] hover:underline" @click="openFolio(event)">Open folio</button></td></tr><tr v-if="folioTabsCounts.Invoices === 0"><td colspan="7" class="px-3 py-12 text-center text-[10px] text-[#82909a]">No event invoices yet. Open an event folio and choose To invoice.</td></tr></tbody></table></div></section>
      <section v-else class="p-3"><div class="mb-3"><h2 class="text-[12px] font-semibold text-[#34414a]">Event receipts</h2><p class="mt-0.5 text-[9px] text-[#7d8991]">Payments recorded against event folios.</p></div><div class="overflow-x-auto rounded-md border border-[#edf0f3]"><table class="w-full min-w-[700px] border-collapse text-left"><thead class="bg-[#fafbfc] text-[8px] font-medium text-[#67737d]"><tr><th class="px-3 py-2.5">Date</th><th class="px-3 py-2.5">Receipt</th><th class="px-3 py-2.5">Event / payer</th><th class="px-3 py-2.5">Method</th><th class="px-3 py-2.5 text-right">Amount</th><th class="px-3 py-2.5">Reference</th></tr></thead><tbody><template v-for="event in events" :key="event.id"><tr v-for="entry in event.folioEntries.filter((item) => item.type === 'Receipt')" :key="entry.id" class="border-t border-[#edf0f3] text-[9px] text-[#46515a]"><td class="px-3 py-2.5">{{ formatDate(entry.date) }}</td><td class="px-3 py-2.5 font-medium text-[#69489a]">{{ entry.id }}</td><td class="px-3 py-2.5">{{ event.name }}<span class="block text-[8px] text-[#8a959c]">{{ event.client }}</span></td><td class="px-3 py-2.5">{{ entry.method }}</td><td class="px-3 py-2.5 text-right">{{ money(entry.amount) }}</td><td class="px-3 py-2.5">{{ entry.reference || '—' }}</td></tr></template><tr v-if="folioTabsCounts.Receipts === 0"><td colspan="6" class="px-3 py-12 text-center text-[10px] text-[#82909a]">No event receipts recorded yet.</td></tr></tbody></table></div></section>
    </div>

    <div v-if="showNewEvent" class="modal-backdrop" @click.self="closeForm">
      <section class="modal-card flex max-h-[92vh] max-w-[920px] flex-col overflow-hidden p-0 text-left" style="width:min(920px, calc(100vw - 32px))" role="dialog" aria-modal="true" aria-labelledby="new-event-title">
        <header class="sticky top-0 z-10 flex items-start justify-between border-b border-[#eee8f1] bg-white px-6 py-5 sm:px-8">
          <div>
            <div class="flex items-center gap-2"><span class="rounded-full bg-[#f1eafa] px-2.5 py-1 text-[8px] font-semibold uppercase tracking-[.12em] text-[#704b99]">Event booking</span><span class="text-[8px] text-[#918894]">Step 1 of 3 · Quote</span></div>
            <h2 id="new-event-title" class="mt-2 font-serif text-[25px] tracking-[-.025em] text-[#30243e]">Create new event</h2>
            <p class="mt-1 text-[10px] text-[#817987]">Capture the client request, schedule, venue, and estimated charges.</p>
          </div>
          <button aria-label="Close event form" class="rounded-md p-2 text-[#8c858f] hover:bg-[#f4f0f5]" @click="closeForm"><X :size="16" /></button>
        </header>

        <div class="min-h-0 flex-1 space-y-4 overflow-y-auto bg-[#faf9fb] px-5 py-5 sm:px-8">
          <div class="grid min-w-0 gap-4 lg:grid-cols-2">
            <section class="min-w-0 rounded-lg border border-[#ebe6ee] bg-white p-4 sm:p-5">
              <div class="mb-4 flex items-start gap-3"><span class="flex size-7 shrink-0 items-center justify-center rounded-full bg-[#f3edf8] text-[10px] font-semibold text-[#69489a]">1</span><div><h3 class="text-[11px] font-semibold text-[#493d50]">Event &amp; client</h3><p class="mt-1 text-[8px] text-[#918894]">Who is hosting and how can we reach them?</p></div></div>
              <div class="space-y-3">
                <label class="form-label">Event name<input v-model="form.name" class="form-input" placeholder="e.g. Ecobank Board Strategy Workshop" /></label>
                <div class="grid min-w-0 gap-3 sm:grid-cols-2"><label class="form-label min-w-0">Organization / client<input v-model="form.client" class="form-input" placeholder="Organization name" /></label><label class="form-label min-w-0">Event type<select v-model="form.kind" class="form-input"><option>Wedding</option><option>Conference</option><option>Workshop</option><option>Social event</option></select></label></div>
                <div class="grid min-w-0 gap-3 sm:grid-cols-2"><label class="form-label min-w-0">Contact phone<input v-model="form.phone" class="form-input" type="tel" placeholder="Phone number" /></label><label class="form-label min-w-0">Contact email<input v-model="form.email" class="form-input" type="email" placeholder="Email address" /></label></div>
                <label class="form-label">Accommodation<select v-model="form.accommodation" class="form-input"><option>Non-residential</option><option>Residential</option></select></label>
              </div>
            </section>

            <section class="min-w-0 rounded-lg border border-[#ebe6ee] bg-white p-4 sm:p-5">
              <div class="mb-4 flex items-start gap-3"><span class="flex size-7 shrink-0 items-center justify-center rounded-full bg-[#f3edf8] text-[10px] font-semibold text-[#69489a]">2</span><div><h3 class="text-[11px] font-semibold text-[#493d50]">Schedule &amp; venue</h3><p class="mt-1 text-[8px] text-[#918894]">Set the dates, expected attendance, and space.</p></div></div>
              <div class="grid min-w-0 grid-cols-2 gap-3"><label class="form-label min-w-0">Start date<input v-model="form.start" class="form-input" type="date" /></label><label class="form-label min-w-0">End date<input v-model="form.end" class="form-input" type="date" :min="form.start" /></label><label class="form-label min-w-0">Start time<input v-model="form.startTime" class="form-input" type="time" /></label><label class="form-label min-w-0">Expected attendees<input v-model="form.pax" class="form-input" type="number" min="1" /></label></div>
              <label class="form-label mt-3 block">Venue<select v-model="form.venue" class="form-input"><option>Grand Ballroom</option><option>Garden Pavilion</option><option>Boardroom</option></select></label>
              <div class="mt-3 flex gap-2 rounded-md bg-[#f7f9fb] p-3 text-[9px] text-[#66737d]"><span class="mt-0.5 text-[#704b99]">●</span><div><strong class="block text-[#44505a]">Venue availability</strong><span>{{ form.start && form.end ? 'Review the selected venue and headcount before confirming this event.' : 'Choose event dates to review venue availability.' }}</span></div></div>
            </section>
          </div>

          <section class="rounded-lg border border-[#e8e1ee] bg-white p-4 sm:p-5">
            <div class="flex items-start gap-3"><span class="flex size-7 shrink-0 items-center justify-center rounded-full bg-[#f3edf8] text-[10px] font-semibold text-[#69489a]">3</span><div><h3 class="text-[11px] font-semibold text-[#493d50]">Estimated charges</h3><p class="mt-1 text-[8px] text-[#918894]">Choose rate lines and quantities to build the quote.</p></div></div>
            <div v-if="applicableRates.length" class="mt-4 grid min-w-0 gap-2 sm:grid-cols-2"><label v-for="rate in applicableRates" :key="rate.id" class="flex min-w-0 items-center justify-between gap-2 rounded-md border border-[#efebf1] bg-[#fcfbfd] px-3 py-2.5 text-[9px] hover:border-[#d9cbe7]"><span class="flex min-w-0 items-center gap-2"><input type="checkbox" class="accent-[#69489a]" :checked="selectedRateIds.includes(rate.id)" @change="toggleRate(rate)" /><span class="min-w-0"><strong class="block truncate text-[#453b4e]">{{ rate.packageName }}</strong><small class="mt-0.5 block text-[#817987]">{{ rate.type }} · {{ money(rate.amount) }}</small></span></span><input v-if="selectedRateIds.includes(rate.id)" v-model.number="rateQuantities[rate.id]" class="form-input w-[76px] shrink-0 py-1 text-right" type="number" min="1" aria-label="Rate quantity" /></label></div>
            <p v-else class="mt-3 rounded-md bg-[#fff8e9] px-3 py-2.5 text-[9px] text-[#846a3d]">No active rates match this client and date range. You can enter an estimate manually.</p>
            <div class="mt-4 grid gap-3 sm:grid-cols-[minmax(0,1fr)_220px] sm:items-end"><label class="form-label">{{ selectedApplicableRates.length ? 'Additional charges (₱)' : 'Estimated event total (₱)' }}<input v-model="form.amount" class="form-input" type="number" min="0" step="0.01" placeholder="0.00" /></label><div class="flex items-center justify-between rounded-md bg-[#f6f1f8] px-3 py-2.5"><span class="text-[9px] text-[#665a70]">Estimated total</span><strong class="font-serif text-[18px] text-[#49305e]">{{ money(formTotal) }}</strong></div></div>
            <p class="mt-3 text-[8px] text-[#918894]">A draft function sheet with duties for Reservations, Kitchen, and Housekeeping is created with the event.</p>
          </section>
        </div>

        <footer class="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-[#eee8f1] bg-white px-5 py-3 sm:px-8"><span class="text-[9px] text-[#817987]">Save this booking as a quote to continue the event flow.</span><div class="flex gap-2"><button class="secondary-button" @click="closeForm">Cancel</button><button class="arrival-action-primary" :disabled="!form.name.trim() || !form.client.trim() || !form.start || !form.end || form.end < form.start || Number(form.pax) < 1 || (!form.amount && !selectedApplicableRates.length) || Number(form.amount) < 0" @click="saveEvent"><Check :size="13" /> Save as quote</button></div></footer>
      </section>
    </div>
    <div v-if="selectedFolio" class="modal-backdrop" @click.self="selectedFolio = null"><section class="modal-card max-h-[92vh] max-w-[980px] overflow-y-auto p-0 text-left" role="dialog" aria-modal="true" aria-labelledby="event-folio-title"><header class="sticky top-0 z-10 flex items-start justify-between border-b border-[#e9e6ec] bg-[#f0faf5] px-5 py-4"><div><p class="text-[8px] font-semibold uppercase tracking-[0.08em] text-[#538266]">Event folio · {{ folioNumber(selectedFolio) }}</p><h2 id="event-folio-title" class="mt-1 font-serif text-[21px] text-[#30243e]">{{ selectedFolio.name }}</h2><p class="mt-1 text-[9px] text-[#66737d]">{{ selectedFolio.client }} · {{ selectedFolio.venue }} · {{ formatDate(selectedFolio.start) }}<span v-if="selectedFolio.end !== selectedFolio.start"> – {{ formatDate(selectedFolio.end) }}</span></p></div><div class="flex items-center gap-3"><span class="rounded-full bg-white px-2.5 py-1 text-[8px] text-[#52785b]">{{ selectedFolio.invoiceStatus || 'Open' }}</span><button aria-label="Close event folio" class="rounded-md p-1.5 text-[#8c858f] hover:bg-white" @click="selectedFolio = null"><X :size="16" /></button></div></header>
      <div class="space-y-4 p-5"><div class="grid gap-2 sm:grid-cols-3"><div class="rounded-md bg-[#f4f7f6] p-3"><small class="text-[8px] text-[#75837e]">Charges</small><strong class="mt-1 block text-[14px] text-[#34414a]">{{ money(eventCharges(selectedFolio)) }}</strong></div><div class="rounded-md bg-[#f4f7f6] p-3"><small class="text-[8px] text-[#75837e]">Payments</small><strong class="mt-1 block text-[14px] text-[#34414a]">{{ money(eventPayments(selectedFolio)) }}</strong></div><div class="rounded-md bg-[#fff7e9] p-3"><small class="text-[8px] text-[#8d754d]">Amount due</small><strong class="mt-1 block text-[14px]" :class="eventBalance(selectedFolio) > 0 ? 'text-[#a25454]' : 'text-[#39764f]'">{{ money(eventBalance(selectedFolio)) }}</strong></div></div>
        <div class="flex flex-wrap items-center gap-2"><button class="secondary-button px-2.5 py-1.5" @click="invoiceEvent(selectedFolio)">To invoice</button><button class="arrival-action-primary px-2.5 py-1.5" @click="openFolioEntry('Charge')"><Plus :size="12" /> Add charge</button><button class="secondary-button px-2.5 py-1.5" @click="openFolioEntry('Debit note')">Debit note</button><button class="secondary-button px-2.5 py-1.5" :disabled="eventBalance(selectedFolio) <= 0" @click="receiptForm = { method: 'Cash', amount: eventBalance(selectedFolio).toFixed(2), reference: '' }; receiptFormOpen = true; folioFormOpen = false">Record receipt</button><span class="flex-1"></span><button class="secondary-button px-2.5 py-1.5" @click="printEvents"><Printer :size="11" /> Print</button></div>
        <div v-if="folioFormOpen" class="grid gap-2 rounded-md border border-[#e7e1eb] bg-[#fcfafd] p-3 sm:grid-cols-[150px_1fr_160px_auto]"><label class="form-label">Entry type<select v-model="folioForm.type" class="form-input mt-1"><option>Charge</option><option>Debit note</option></select></label><label class="form-label">Description<input v-model="folioForm.description" class="form-input mt-1" :placeholder="folioForm.type === 'Charge' ? 'Venue, catering, equipment...' : 'Reason for debit note'" /></label><label class="form-label">Amount (₱)<input v-model="folioForm.amount" class="form-input mt-1" type="number" min="0.01" step="0.01" /></label><div class="flex items-end gap-1"><button class="secondary-button" @click="folioFormOpen = false">Cancel</button><button class="arrival-action-primary" :disabled="!folioForm.description.trim() || Number(folioForm.amount) <= 0" @click="addFolioEntry">Post</button></div></div>
        <div v-if="receiptFormOpen" class="grid gap-2 rounded-md border border-[#e7e1eb] bg-[#fcfafd] p-3 sm:grid-cols-[160px_160px_1fr_auto]"><label class="form-label">Method<select v-model="receiptForm.method" class="form-input mt-1"><option>Cash</option><option>Card</option><option>Mobile money</option><option>Bank transfer</option></select></label><label class="form-label">Amount (₱)<input v-model="receiptForm.amount" class="form-input mt-1" type="number" min="0.01" step="0.01" :max="eventBalance(selectedFolio)" /></label><label class="form-label">Reference<input v-model="receiptForm.reference" class="form-input mt-1" placeholder="Optional receipt / transaction reference" /></label><div class="flex items-end gap-1"><button class="secondary-button" @click="receiptFormOpen = false">Cancel</button><button class="arrival-action-primary" :disabled="Number(receiptForm.amount) <= 0 || Number(receiptForm.amount) > eventBalance(selectedFolio)" @click="addReceipt">Receive</button></div></div>
        <section class="overflow-x-auto rounded-md border border-[#eeeaf0]"><div class="border-b border-[#eeeaf0] px-3 py-2.5"><h3 class="text-[10px] font-semibold text-[#493d50]">Account activity</h3></div><table class="w-full min-w-[760px] border-collapse text-left"><thead class="bg-[#fafbfc] text-[8px] text-[#67737d]"><tr><th class="px-3 py-2">Date</th><th class="px-3 py-2">Description</th><th class="px-3 py-2">Reference</th><th class="px-3 py-2">Type</th><th class="px-3 py-2 text-right">Amount</th><th class="px-3 py-2">Status</th><th class="px-3 py-2"></th></tr></thead><tbody><tr v-for="entry in selectedFolio.folioEntries" :key="entry.id" class="border-t border-[#f0edf1] text-[9px] text-[#514958]" :class="entry.status === 'Voided' ? 'opacity-55' : ''"><td class="px-3 py-2.5">{{ formatDate(entry.date) }}</td><td class="px-3 py-2.5"><strong class="font-medium">{{ entry.description }}</strong><span v-if="entry.voidReason" class="block text-[8px] text-[#a25454]">Void reason: {{ entry.voidReason }}</span><span v-if="entry.method" class="block text-[8px] text-[#817987]">{{ entry.method }}</span></td><td class="px-3 py-2.5">{{ entry.reference || '—' }}</td><td class="px-3 py-2.5">{{ entry.type }}</td><td class="px-3 py-2.5 text-right" :class="entry.status === 'Voided' ? 'line-through text-[#8b8490]' : ''">{{ entry.type === 'Receipt' ? '− ' : '' }}{{ money(entry.amount) }}</td><td class="px-3 py-2.5">{{ entry.status }}</td><td class="px-3 py-2.5 text-right"><button v-if="entry.status === 'Posted'" class="text-[8px] font-medium text-[#9a6570] hover:underline" @click="folioEntryToVoid = entry">Void</button></td></tr><tr v-if="selectedFolio.folioEntries.length === 0"><td colspan="7" class="px-3 py-12 text-center text-[9px] text-[#87929a]">No charges or payments on this folio yet.</td></tr></tbody><tfoot class="border-t border-[#eeeaf0] bg-[#fcfbfd] text-[9px]"><tr><td colspan="4" class="px-3 py-2 text-right text-[#817987]">Folio balance</td><td class="px-3 py-2 text-right font-semibold text-[#44394c]">{{ money(eventBalance(selectedFolio)) }}</td><td colspan="2"></td></tr></tfoot></table></section>
      </div><footer class="flex flex-wrap items-center justify-between gap-2 border-t border-[#e9e6ec] px-5 py-3"><span class="text-[8px] text-[#8b8490]">{{ selectedFolio.id }} · {{ selectedFolio.pax }} attendees · Estimated event value {{ money(selectedFolio.amount) }}</span><div class="flex gap-2"><button class="secondary-button" @click="selectedFolio = null">Close</button><button v-if="selectedFolio.invoiceNumber" class="arrival-action-primary" @click="printEvents"><FileText :size="12" /> {{ selectedFolio.invoiceNumber }}</button></div></footer>
    </section></div>
    <div v-if="folioEntryToVoid" class="modal-backdrop z-[80]" @click.self="folioEntryToVoid = null"><section class="modal-card max-w-[420px] text-left" role="dialog" aria-modal="true" aria-labelledby="void-event-entry-title"><p class="eyebrow">Folio audit trail</p><h2 id="void-event-entry-title" class="mt-1 font-serif text-[21px] text-[#30243e]">Void this entry?</h2><p class="mt-2 text-[9px] text-[#817987]">{{ folioEntryToVoid.description }} · {{ money(folioEntryToVoid.amount) }}. The entry will remain in the event folio.</p><label class="form-label mt-4">Reason<input v-model="voidReason" class="form-input mt-1" placeholder="Reason required" /></label><footer class="mt-4 flex justify-end gap-2"><button class="secondary-button" @click="folioEntryToVoid = null">Cancel</button><button class="rounded-md bg-[#a25454] px-3 py-2 text-[9px] font-medium text-white" :disabled="!voidReason.trim()" @click="voidFolioEntry">Void entry</button></footer></section></div>

    <div v-if="functionEvent" class="modal-backdrop" @click.self="functionEvent = null"><section class="modal-card max-h-[92vh] max-w-[980px] overflow-y-auto p-0 text-left" role="dialog" aria-modal="true" aria-labelledby="function-sheet-title"><header class="sticky top-0 z-10 flex items-start justify-between border-b border-[#e9e6ec] bg-[#fffdfb] px-5 py-4"><div><p class="eyebrow">Function sheet</p><h2 id="function-sheet-title" class="mt-1 font-serif text-[21px] text-[#30243e]">{{ functionEvent.name }}</h2><div class="mt-2 flex flex-wrap gap-1.5"><span class="rounded-full bg-[#edf2fa] px-2 py-1 text-[8px] text-[#4c709e]">{{ functionEvent.venue }}</span><span class="rounded-full bg-[#e8f5ed] px-2 py-1 text-[8px] text-[#39764f]">{{ formatDate(functionEvent.start) }}</span><span class="rounded-full bg-[#fff2df] px-2 py-1 text-[8px] text-[#8c6838]">{{ functionEvent.pax }} guests</span></div></div><button class="rounded-md p-1.5 text-[#8c858f] hover:bg-[#f4f0f5]" aria-label="Close function sheet" @click="functionEvent = null"><X :size="16" /></button></header>
      <div class="flex flex-wrap gap-1 border-b border-[#eeeaf0] px-5 pt-3"><button v-for="tab in (['Event', 'Setup', 'Catering', 'Timeline', 'Tasks'] as const)" :key="tab" class="border-b-2 px-2.5 pb-2 text-[9px]" :class="functionTab === tab ? 'border-[#69489a] font-semibold text-[#604283]' : 'border-transparent text-[#807884]'" @click="functionTab = tab">{{ tab }}</button></div>
      <div class="space-y-4 p-5">
        <template v-if="functionTab === 'Event'"><section><h3 class="mb-2 text-[10px] font-semibold text-[#493d50]">Client &amp; contact</h3><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-md bg-[#f7f8fa] p-3 text-[8px] text-[#7d8790]">Event<strong class="mt-1 block text-[9px] text-[#34414a]">{{ functionEvent.name }}</strong></div><div class="rounded-md bg-[#f7f8fa] p-3 text-[8px] text-[#7d8790]">Organization<strong class="mt-1 block text-[9px] text-[#34414a]">{{ functionEvent.client }}</strong></div><label class="form-label">Coordinator<select v-model="functionEvent.coordinator" class="form-input mt-1"><option>Unassigned</option><option>Jordan Lee</option><option>Amelia Santos</option><option>Marco Reyes</option></select></label><div class="rounded-md bg-[#f7f8fa] p-3 text-[8px] text-[#7d8790]">Contact<strong class="mt-1 block text-[9px] text-[#34414a]">{{ functionEvent.contactName }} · {{ functionEvent.phone || 'Phone not provided' }}</strong></div></div></section><section><h3 class="mb-2 text-[10px] font-semibold text-[#493d50]">Schedule</h3><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><label class="form-label">Venue<input v-model="functionEvent.venue" class="form-input mt-1" /></label><label class="form-label">Start<input v-model="functionEvent.start" class="form-input mt-1" type="date" /></label><label class="form-label">End<input v-model="functionEvent.end" class="form-input mt-1" type="date" /></label><label class="form-label">Guests<input v-model.number="functionEvent.pax" class="form-input mt-1" type="number" min="1" /></label></div><label class="form-label mt-3 block">Coordinator notes<textarea v-model="functionEvent.coordinatorNotes" class="form-input mt-1 min-h-20" placeholder="Event updates and client requests" /></label></section></template>
        <template v-else-if="functionTab === 'Setup'"><section><h3 class="mb-3 text-[10px] font-semibold text-[#493d50]">Room &amp; venue setup</h3><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><label class="form-label">Layout<select v-model="functionEvent.layout" class="form-input mt-1"><option>Banquet style</option><option>Classroom</option><option>Theatre</option><option>Boardroom</option><option>U-shape</option></select></label><label class="form-label">Tables<input v-model.number="functionEvent.tables" class="form-input mt-1" type="number" min="0" /></label><label class="form-label">Chairs<input v-model.number="functionEvent.chairs" class="form-input mt-1" type="number" min="0" /></label><label class="form-label">Capacity<input v-model.number="functionEvent.pax" class="form-input mt-1" type="number" min="1" /></label><label class="form-label">Registration desks<input v-model.number="functionEvent.registration" class="form-input mt-1" type="number" min="0" /></label><label class="form-label">Displays / signs<input v-model.number="functionEvent.display" class="form-input mt-1" type="number" min="0" /></label><label class="form-label">Guest access<select v-model="functionEvent.access" class="form-input mt-1"><option>Main entrance</option><option>East entrance</option><option>Accessible entrance</option></select></label><label class="form-label">Parking<select v-model="functionEvent.parking" class="form-input mt-1"><option>Available for guests</option><option>Reserved parking</option><option>Limited parking</option></select></label></div><label class="form-label mt-3 block">Setup notes<textarea v-model="functionEvent.setupNotes" class="form-input mt-1 min-h-20" /></label></section><div class="rounded-md bg-[#f4f8fe] p-3 text-[9px] text-[#567199]"><BedDouble :size="13" class="mr-1 inline" /> Housekeeping receives this setup in the shared function briefing.</div></template>
        <template v-else-if="functionTab === 'Catering'"><section><h3 class="mb-3 text-[10px] font-semibold text-[#493d50]">Food &amp; beverage service</h3><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><label class="form-label">Service style<select v-model="functionEvent.service" class="form-input mt-1"><option>Formal</option><option>Buffet</option><option>Cocktail</option><option>Refreshments only</option></select></label><label class="form-label">Meal service<select v-model="functionEvent.meal" class="form-input mt-1"><option>Plated service</option><option>Buffet</option><option>Set menu</option><option>Refreshments only</option></select></label><label class="form-label">Tea breaks<input v-model.number="functionEvent.teaBreaks" class="form-input mt-1" type="number" min="0" /></label><label class="form-label">Special diets<input v-model.number="functionEvent.specialDiets" class="form-input mt-1" type="number" min="0" /></label><label class="form-label sm:col-span-2">Dietary notes<textarea v-model="functionEvent.dietaryNotes" class="form-input mt-1 min-h-16" /></label><label class="form-label sm:col-span-2">Allergies<textarea v-model="functionEvent.allergies" class="form-input mt-1 min-h-16" /></label><label class="form-label sm:col-span-2">Beverages<textarea v-model="functionEvent.beverages" class="form-input mt-1 min-h-16" /></label><label class="form-label sm:col-span-2">Snacks<textarea v-model="functionEvent.snacks" class="form-input mt-1 min-h-16" /></label></div></section><div class="rounded-md bg-[#fff8e9] p-3 text-[9px] text-[#846a3d]"><Utensils :size="13" class="mr-1 inline" /> Kitchen receives the guest count, menu, dietary, and service timing details in this briefing.</div></template>
        <template v-else-if="functionTab === 'Timeline'"><div class="flex items-center justify-between"><div><h3 class="text-[10px] font-semibold text-[#493d50]">Event run of show</h3><p class="mt-1 text-[8px] text-[#827987]">Shared sequence for all departments.</p></div><button class="secondary-button px-2 py-1.5" @click="functionEvent.timeline.push({ time: '10:00', item: 'New schedule item', department: 'Reservations' })"><Plus :size="11" /> Add item</button></div><div class="mt-3 space-y-2"><div v-for="(item, index) in functionEvent.timeline" :key="index" class="grid gap-2 rounded-md border border-[#eeeaf0] p-2 sm:grid-cols-[90px_1fr_150px_auto]"><label class="form-label">Time<input v-model="item.time" class="form-input mt-1" type="time" /></label><label class="form-label">Activity<input v-model="item.item" class="form-input mt-1" /></label><label class="form-label">Lead department<select v-model="item.department" class="form-input mt-1"><option>Reservations</option><option>Kitchen</option><option>Housekeeping</option></select></label><button class="self-end rounded p-2 text-[#9a6570] hover:bg-[#fbf1f2]" aria-label="Remove schedule item" @click="removeTimelineItem(index)"><X :size="13" /></button></div></div></template>
        <template v-else><div class="flex flex-wrap items-center justify-between gap-2"><div><h3 class="text-[10px] font-semibold text-[#493d50]">Department duties</h3><p class="mt-1 text-[8px] text-[#827987]">One briefing shared with Reservations, Kitchen, and Housekeeping.</p></div><button class="secondary-button px-2 py-1.5" @click="functionEvent.tasks.push({ id: `task-${Date.now()}`, department: 'Reservations', duty: 'New department task', owner: 'Unassigned', due: functionEvent.start, complete: false })"><Plus :size="11" /> Add task</button></div><div class="mt-3 space-y-2"><article v-for="task in functionEvent.tasks" :key="task.id" class="grid gap-2 rounded-md border border-[#eeeaf0] p-3 sm:grid-cols-[140px_1fr_145px_130px_auto]"><label class="form-label">Department<select v-model="task.department" class="form-input mt-1"><option>Reservations</option><option>Kitchen</option><option>Housekeeping</option></select></label><label class="form-label">Duty<input v-model="task.duty" class="form-input mt-1" /></label><label class="form-label">Owner<input v-model="task.owner" class="form-input mt-1" /></label><label class="form-label">Due date<input v-model="task.due" class="form-input mt-1" type="date" /></label><label class="flex items-center gap-2 self-end rounded-md bg-[#f7f8fa] px-3 py-2 text-[8px] text-[#59656e]"><input v-model="task.complete" type="checkbox" class="accent-[#69489a]" /> Done</label></article></div></template>
      </div>
      <footer class="sticky bottom-0 flex flex-wrap items-center justify-between gap-2 border-t border-[#e9e6ec] bg-[#fffdfb] px-5 py-3"><span class="text-[8px] text-[#8b8490]">{{ functionEvent.id }} · {{ functionEvent.kind }} · {{ functionEvent.accommodation }}</span><div class="flex gap-2"><button v-if="functionEvent.status !== 'Completed'" class="secondary-button" @click="advanceEventStatus">{{ functionEvent.status === 'Quote' ? 'Confirm event' : 'Mark completed' }}</button><button class="secondary-button" @click="functionEvent = null">Close</button><button class="arrival-action-primary" @click="saveFunction"><Check :size="13" /> Save function sheet</button></div></footer>
    </section></div>
  </section>
</template>
